var officialManifests = [
  {
    id: "html-import",
    name: "Browser HTML Bookmarks",
    version: "1.0.0",
    description: "Import and export bookmarks, folders, and tags using the standard Netscape HTML bookmarks format used by Chrome, Firefox, Safari, Edge, and Arc.",
    author: "tessera.community",
    permissions: ["bookmarks.read", "bookmarks.write", "tags.write"],
    ui: {
      commands: ["import-html-file", "export-html-file"]
    }
  },
  {
    id: "markdown-export",
    name: "Markdown Exporter",
    version: "1.0.0",
    description: "Export all bookmarks grouped by collection or tag into clean Markdown.",
    author: "tessera.community",
    permissions: ["bookmarks.read", "tags.read", "collections.read"],
    ui: {
      commands: ["export-to-markdown"]
    }
  }
];

class ExtensionRegistry {
  registry = new Map;
  constructor() {
    for (const manifest of officialManifests) {
      this.registry.set(manifest.id, manifest);
    }
  }
  listExtensions() {
    return Array.from(this.registry.values());
  }
  getExtension(id) {
    return this.registry.get(id);
  }
  registerExtension(manifest) {
    this.registry.set(manifest.id, manifest);
  }
}
var extensionRegistry = new ExtensionRegistry;

// server/src/relay/store.ts
import fs from "node:fs";
import path from "node:path";

class SyncRelayStore {
  globalCursor = 0;
  changelog = [];
  devices = new Map;
  storageFilePath;
  constructor() {
    let dataDir = process.env["DATA_DIR"];
    if (!dataDir) {
      if (process.env["VERCEL"] || process.env["AWS_LAMBDA_FUNCTION_NAME"]) {
        dataDir = path.join("/tmp", "tessera-data");
      } else {
        dataDir = path.resolve(process.cwd(), "data");
      }
    }
    try {
      if (!fs.existsSync(dataDir)) {
        fs.mkdirSync(dataDir, { recursive: true });
      }
    } catch {}
    this.storageFilePath = path.join(dataDir, "relay_changelog.json");
    this.loadFromDisk();
  }
  loadFromDisk() {
    try {
      if (fs.existsSync(this.storageFilePath)) {
        const raw = fs.readFileSync(this.storageFilePath, "utf-8");
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed.changelog)) {
          this.changelog = parsed.changelog;
          this.globalCursor = typeof parsed.globalCursor === "number" ? parsed.globalCursor : this.changelog.length;
        }
        if (Array.isArray(parsed.devices)) {
          for (const d of parsed.devices) {
            this.devices.set(d.id, d);
          }
        }
      }
    } catch (err) {
      console.warn("[SyncRelayStore] Could not load changelog from disk:", err);
    }
  }
  async saveToDiskAsync() {
    try {
      const dir = path.dirname(this.storageFilePath);
      await fs.promises.mkdir(dir, { recursive: true });
      const data = {
        globalCursor: this.globalCursor,
        changelog: this.changelog,
        devices: Array.from(this.devices.values())
      };
      const tmpPath = `${this.storageFilePath}.${Date.now()}.${Math.random().toString(36).slice(2)}.tmp`;
      await fs.promises.writeFile(tmpPath, JSON.stringify(data, null, 2), "utf-8");
      await fs.promises.rename(tmpPath, this.storageFilePath);
    } catch (err) {
      console.warn("[SyncRelayStore] Could not persist changelog to disk (memory relay active):", err);
    }
  }
  saveToDisk() {
    this.saveToDiskAsync();
  }
  registerDevice(device) {
    this.devices.set(device.id, device);
    this.saveToDisk();
  }
  listDevices() {
    return Array.from(this.devices.values());
  }
  appendDeltas(deltas) {
    const now = new Date().toISOString();
    for (const delta of deltas) {
      this.globalCursor++;
      this.changelog.push({
        cursor: this.globalCursor,
        delta,
        receivedAt: now
      });
    }
    this.saveToDisk();
    return {
      nextCursor: this.globalCursor,
      count: deltas.length
    };
  }
  getDeltasSince(sinceCursor, limit = 100) {
    const matching = this.changelog.filter((entry) => entry.cursor > sinceCursor);
    const sliced = matching.slice(0, limit);
    const hasMore = matching.length > limit;
    const nextCursor = sliced.length > 0 ? sliced[sliced.length - 1].cursor : sinceCursor;
    return {
      deltas: sliced.map((entry) => entry.delta),
      nextCursor,
      hasMore
    };
  }
  wipeAll() {
    this.changelog = [];
    this.devices.clear();
    this.globalCursor = 0;
    try {
      if (fs.existsSync(this.storageFilePath)) {
        fs.unlinkSync(this.storageFilePath);
      }
    } catch {}
  }
}
var relayStore = new SyncRelayStore;

